PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?father ?fatherLabel ?deathDate WHERE {
  VALUES ?person { <http://dbpedia.org/resource/Badi'_al-Zaman_Mirza> }
  {
    ?person dbo:father ?father .
  } UNION {
    ?person dbp:father ?father .
  } UNION {
    ?person dbo:parent ?father .
  } UNION {
    ?person dbp:parent ?father .
  }
  OPTIONAL { ?father (dbo:deathDate|dbp:deathDate|dbp:dateOfDeath|dbp:death_date) ?deathDate. }
  OPTIONAL { ?father rdfs:label ?fatherLabel. FILTER(lang(?fatherLabel) = "en") }
}

